mapper.update:
update `spu_order` t set t.order_state = #{toState,jdbcType=INTEGER},
t.close_reason = #{closeReason,jdbcType=VARCHAR},
t.order_state_log = CONCAT(t.order_state_log, ',', #{toState,jdbcType=INTEGER}) where t.order_no = #{orderNo,jdbcType=VARCHAR} and t.order_state = #{sourceState,jdbcType=INTEGER}

update spu_order
`refund_quantity` = `refund_quantity` + #{refundQuantity}, `is_refunding` = CASE WHEN `is_refunding` = 0 THEN 1 ELSE `is_refunding` END
where `spu_order_no` = #{spuOrderNo,jdbcType=VARCHAR}

update spu_order t set t.refund_quantity = t.refund_quantity -
(select sum(t1.refunding_quantity) from sku_order t1 where t1.sku_order_no in

        #{item,jdbcType=VARCHAR}

)
where t.spu_order_no = #{spuOrderNo,jdbcType=VARCHAR}

mapper.select:
SELECT t1.order_no, t1.order_state as current_state, MIN(t.order_state) as to_state, t1.channel_id, t1.out_order_no, t1.order_type FROM spu_order t left join `order` t1 on t.order_no = t1.order_no WHERE t1.order_no IN
#{item,jdbcType=VARCHAR}
and t.del_flag = 0 GROUP BY t1.order_no
